INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIEL', 'Se attivato, consente di eseguire la protocollazione con il sistema INSIEL, deve essere anche inserita la strina PROTOCOLLO_INSIEL nel parametro TIPOPROTOCOLLO della verticalizzazione PROTOCOLLO_ATTIVO.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIEL', 'URL', 'Indicare l''url del web service per eseguire la protocollazione con il protocollo INSIEL.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIEL', 'CODICEUTENTE', 'E'' l''utente con cui avviene l''autenticazione al web service che coincide con quello cui avviene la protocollazione; se non valorizzato il sistema andrà a cercare il valore nel parametro OPERATORE della verticalizzazione PROTOCOLLO_ATTIVO, in quanto, da questo parametro, è possibile utilizzare dei segnalibri nel caso in cui gli operatori del protocollo siano mappati con quelli del backoffice.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIEL', 'PASSWORD', 'E'' la password dell''utente segnalato sul parametro CODICEUTENTE utilizzata per autenticarsi, va valorizzata nel caso in cui sia valorizzato il parametro CODICEUTENTE.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIEL', 'URL_UPLOADFILE', 'Indica l''url del web service utilizzato per fare l''upload degli allegati utilizzando .net, il parametro è obbligatorio altrimenti la protocollazione andrebbe a si buon fine, ma non sarebbe possibile spedire gli allegati (verrà quindi restituita comunque un''eccezione anche se la protocollazione sarà eseguita)'); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_ATTIVO', 'LISTA_CARATTERI_DA_ELIMINARE', 'Indica i caratteri da eliminare nei nomi file in un eventuale passaggio di allegati al protocollo. Alcuni web service di protocollo restituiscono un''eccezione nel caso in cui nel nome file dei documenti passati siano presenti alcuni caratteri, come ad esempio Iride che non accetta i caratteri accentati e gli apici singoli nel nome file. I caratteri inseriti in questo parametro devono essere divisi dal carattere | ( ad esempio ''|à|è|ì|ò|ù|/|& ).');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIEL', 'CODICEREGISTRO', 'Il protocollo Insiel ha la necessità di sapere in quale registro protocollare, è quindi un dato che il web service richiede in modo obbligatorio. Deve essere fornito da Insiel o da un amministratore di protocollo presso il comune. Nell''ambiente di test generico fornito dall''azienda Insiel (url: http://193.42.71.39:8081/WsProtocollo/services/protocollo) il codice è GEN (sta per protocollo generale).'); 
INSERT INTO MAPOGGETTI (NOMECAMPO, nometabella) VALUES ('CODICEOGGETTO','DOMANDESTC_ALLEGATI');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIEL', 'CODICE_UFFICIO_OPERANTE', 'Indica il codice ufficio operante del protocollo di Insiel DA NON CONFONDERE con il codice ufficio che va configurato sull''amministrazione nel campo RUOLO e va di pari passo con il registro.');
