INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('PROTOCOLLO_APSYSTEMS', 'Protocollo ApSystems è un sistema di protocollo che espone web service per eseguire le sue funzionalità, l''azienda proprietaria è A.P. SYSTEMS di Magenta. Il protocollo è presente ad esempio al Comune di Viareggio. Vanno valorizzati necessariamente i parametri URL, USERNAME e PASSWORD.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_APSYSTEMS', 'URL', '(Obbligatorio) Indica l''url del web service di Ap Systems da utilizzare nell''ambiente scelto (Test o Produzione). Se si desidera utilizzare un ambiente di test inserire il valore http://193.42.71.39:8081/WsProtocollo/services/protocollo <http://193.42.71.39:8081/WsProtocollo/services/protocollo> , è un ambiente di sviluppo creato dai programmatori di ApSystems appositamente per fare le prove.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_APSYSTEMS', 'USERNAME', '(Obbligatorio) Credenziale di accesso al web service, indica lo username con cui autenticarsi, se non utilizzato non è possibile invocare le funzionalità di protocollazione. In ambiente di test è stato utilizzato il valore "APS"');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_APSYSTEMS', 'PASSWORD', '(Obbligatorio) Credenziale di accesso al web service, indica la password con cui autenticarsi, va in coppia con il parametro USERNAME di questa verticalizzazione, se non utilizzato non è possibile invocare le funzionalità di protocollazione. In ambiente di test è stato utilizzato il valore "TestInAPS"');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE(MODULO,PARAMETRO, DESCRIZIONE)VALUES('STC','LISTA_NODI_NON_AGG_ANAGRAFE','Contiene la lista degli identificativi dei nodi che durante l''inserimento di una pratica tramite STC non devono aggiornare i dati presenti nell''anagrafica (se esistente). Il carattere di separazione è la virgola (,)');
INSERT INTO MAPOGGETTI (NOMETABELLA, NOMECAMPO) VALUES ('MOVIMENTI','CODICEOGGETTO_NOTIFICA');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('AREA_RISERVATA', 'URL_APPLICAZIONE_FACCT', 'Url completo dell''applicazione FACCT che costruisce la domanda online secondo l''RFC 186 del CART (es: http://10.20.46.8:8080/CART-FACCT/presentazionedomanda/elencoEndo.htm)');
INSERT INTO FO_CONFIGURAZIONEBASE(CODICE, ETICHETTA, CHIAVE,FK_CONTESTO) VALUES ('73', 'Autorizzazioni', ''''' AS AUTORIZZAZIONI','AIP-LIS');
insert into verticalizzazioniparametribase (modulo,parametro,descrizione)  values  ('STC','NLA_IDNODO_CART_COMINTERNE',' Id del nodo NLA NLA-CART-COMUNICAZIONIINTERNE registrato su STC (utilizzato per individuare le chiamate provenienti da frontend CART compliant) ') ;
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIEL', 'TIPI_DOCUMENTO_WS', 'Indica la modalità di recupero dati dei tipi documento. Questi possono essere recuperati dalla tabella di VBG Protocollo_TipiDocumento, SE VALORIZZATO A 0 OPPURE A NULL, oppure direttamente dal web service di Insiel, invocando il metodo getTipiDoc, SE VALORIZZATO A 1. Nel primo caso i dati saranno più gestibili, ad esempio indicando solamente i tipi documento necessari all''integrazione, nel secondo avremmo un allineamento certo dei dati in quanto vengono invocati direttamente dagli archivi del protocollo, ma potrebbe anche esserci una mole di dati enorme che renderebbe difficoltosa la gestione di questo dato agli operatori; ad esempio al Comune di Trieste sono presenti più di 200 tipi documento, mentre ne viene utilizzato solamente uno, almeno per le pratiche provenienti da VBG.'); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_DOCPRO', 'MODALITA_TRASMISSIONE', 'Questo parametro è utilizzato per i protocolli in partenza del Protocollo DOCPRO, un protocollo in partenza deve necessariamente scatenare, lato sistema di protocollazione, l''invio di una PEC; quest''evento viene scatenato in base al valore indicato in questo parametro che, ad esempio, al Comune di Empoli è ''e-mail''. Il valore indicato andrà a riempire l''attributo ''nome'' dell''elemento ''modalitatramissione'' presente dentro al nodo ''ApplicativoProtocollo'''); 
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('NLA-RICEZIONE-PEC', 'NOTIFICA_CON_ALLEGATI', 'Se posto a S invia gli allegati delle notifiche al web service di notifica PEC (movimentiMailWS), altrimenti il nodo nla-pec non invierà gli allegati a tale web service.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('NLA-RICEZIONE-PEC', 'STRATEGIA_DI_LETTURA_MESSAGGI', 'I valori ammessi sono 0,1 o 2. Se posto a 0 o non valorizzato vengono lette tutte le mail non lette presenti nella INBOX (comportamento di default), se posto a 1 legge tutte le mail presenti nella INBOX, se posto a 2 legge tutte le mail presenti nella INBOX arrivate nell’ultima settimana ');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('NLA-RICEZIONE-PEC', 'PEC_NON_FORMATTATA', 'Può assumere i valori S o N, se posto a S l''applicativo controlla se l''oggetto della PEC soddisfa l''espressione regolare (indicata nel parametro PEC_NON_FORMATTATA_FILTRO) e nel caso tale controllo abbia esito positivo, si procede alla creazione di una nuova pratica con le informazioni contenute in tale messaggio.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('NLA-RICEZIONE-PEC', 'PEC_NON_FORMATTATA_FILTRO', 'Tale parametro deve contenere l''espressione regolare per individuare quali messaggi processare secondo la logica indicata nel parametro PEC_NON_FORMATTATA.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('NLA-RICEZIONE-PEC', 'PEC_NON_FORMATTATA_ANAG_RIC','Tale parametro deve contenere l’ID di un richiedente già censito nell''applicativo che comparirà come richiedente della pratica secondo la logica indicata nel parametro PEC_NON_FORMATTATA.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'RISPOSTA_IMMEDIATA', 'I valori ammessi sono S o N. Se posto a S il web service restituisce a Connects la risposta immediatamente, se valorizzato a N la risposta a Connects avviene solo dopo l''inserimento della pratica nel backoffice (Valore di default = N). Questo parametro e'' stato inserito per evitare che per pratiche di dimensioni grandi, il client di Connects vada in TimeOut');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'VERTICALIZZAZIONE_RAVENNA','I valori ammessi sono S o N. Se posto a S, all''interno del codice vengono fatte operazioni richieste soltanto per il Comune e la Provincia di Ravenna, per sapere nel dettaglio le personalizzazioni fatte fare riferimento al documento Sigepro2_NLAPeople.doc della commessa 1359-2008 sul software della Qualita'' (Valore di default = N).');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'IMPORT_ALLEGATI_AUTOMATICO','I valori ammessi sono S o N. Se posto a S, gli allegati presenti nella pratica People, vengono inseriti automaticamente nell''XML inviato a STC, se posto a N nella pratica STC viene inserito soltanto l''ID dell''allegato, in questo caso per caricare gli allegati nella pratica VBG bisogna andare nella relativa sezione Documenti ed effettuare il download (Valore di default = S)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'DESC_RUOLO_SOGGETTO','Va valorizzato con la descrizione del Ruolo Soggetto definito in VBG, con il quale si andra'' a comporre la sezione dell''anagrafica (sezione Altri Soggetti) da inviare a STC (Parametro obbligatorio)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'STC_USER','UserName per l''autenticazione all''STC (ricordarsi di censire in quest''ultimo l''utente -NLAPEOPLE-');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'STC_PASSWORD','Password per l''autenticazione all''STC (ricordarsi di censire in quest''ultimo l''utente -NLAPEOPLE-). Parametro obbligatorio');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'URL_NOTIFICA_PEOPLE','URL per notificare a People l''arrivo della pratica in VBG (va cambiato solo l''IP e la porta. Es. http://suaper.lepida.it:8080/BEService/services/setEventService). Parametro obbligatorio');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'URL_PUBBLICO_VISURA','URL per notificare a People l''URL per fare visura delle pratiche (solitamente va cambiato solo l''IP e la porta. Es. http://localhost:8080/NLAPeople/services/NLAVisuraService). Parametro obbligatorio');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'NOTIFICA_ANOMALIE','I valori ammessi sono S o N. Se posto a S, in caso di errore in fase di inserimento pratica in VBG, viene inviata una mail di anomalia all''indirizzo specificato nel parametro LISTAMAIL_NOTIFICA, se posto a N non viene inviata nessuna email di anomalia (valore di default = N).');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'DOCUMENTI_INTO_PROC','I valori ammessi sono S o N. Se posto a S i documenti presenti nella pratica People vengono associati ai rispettivi procedimenti, se posto a N i documenti vengono inseriti nella sezione generale dei documenti della pratica (Valore di default = N)');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'XMLMOD_DENOM_VIA','Parametro per individuare la VIA della localizzazione nella pratica people tramite identificativo XML_MOD');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'XMLMOD_CIVICO','Parametro per individuare il CIVICO della localizzazione nella pratica people tramite identificativo XML_MOD');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'XMLMOD_FOGLIO','Parametro per individuare il FOGLIO della localizzazione nella pratica people tramite identificativo XML_MOD');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'XMLMOD_MAPPALE','Parametro per individuare il MAPPALE della localizzazione nella pratica people tramite identificativo XML_MOD');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'XMLMOD_SUB','Parametro per individuare il SUB della localizzazione nella pratica people tramite identificativo XML_MOD');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'XMLMOD_TIPOCATASTO_T','Parametro per individuare il TIPO CATASTO TERRENI della localizzazione nella pratica people tramite identificativo XML_MOD');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'XMLMOD_TIPOCATASTO_F','Parametro per individuare il TIPO CATASTO FABBRICATI della localizzazione nella pratica people tramite identificativo XML_MOD');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'LISTAMAIL_NOTIFICA','Parametro contenente la lista degli indirizzi mail a cui inviare le notifiche di anomalie (gli indirizzi email devono essere separati da '';''. Tale parametro e'' obbligatorio se il parametro NOTIFICA_ANOMALIE e'' posto a S.');                
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'UID_NODO_NLA','Identificatore univoco del nodo NLA di People nell''istallazione (se presente un solo nodo NLA-People va lasciato a 1)');              
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'URL_INSERIMENTO_ALLEGATIPEOPLE','URL per inviare a People eventuali allegati prodotti dall''elaborazione dell''istanza dentro VBG tramite notifica attivita'' (Es. http://peopledemo:8080/AllegatiService/services/allegatiService)');               
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'ID_COMMUNE_ISTALLAZIONE_PEOPLE','Identificatore univoco dell''ID Commune dell''istallazione di People (quello presente nella PeopleConsole), parametro necessario solo se si vuole inviare a People eventuali allegati prodotti in VBG.');                
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PEOPLE', 'ENABLE_MTOM','I valori ammessi sono S o N. Se posto a S le comunicazioni verso VBG avvengono utilizzando la tecnologia MTOM (Valore di default = S).');
