UPDATE verticalizzazioniparametribase SET descrizione ='URL completo del componente Anagrafe Seacher. Se presente sovrascrive quello di default che punta al compomente doNet.   Es. http://&lt;ip-servert>:&lt;port>/webapp/services/name_sercices?wsdl (http://devel9:8080/nla-pdd-ri/services/anagrafe?wsdl)' WHERE  modulo='WSANAGRAFE' and parametro='URL';







update Verticalizzazioniparametribase set DESCRIZIONE='Url del web service (wsdl) da invocare per ricavare i dati anagrafici. 
Es. ER: https://servizicner.regione.emilia-romagna.it/parixgate/services/gate 
Es. CART tramite PDD: https://nal-test:8443/cart/PD/SPCCfirenze/SPCRegioneToscana/SPCParixgate/RicercaImpresePerCodiceFiscale 
Nel browser del server application aggiungendo alla URL ''?wsdl'' si può verificare se il server raggiunge il servizio.' where Modulo='WSANAGRAFE_PARIX' and Parametro='URL';

